//! 确定性差分测试用例生成器。
//!
//! golden 数据(generated by `examples/golden_gen.rs`,以 C++ 后端为准)与
//! 双后端差分测试(`tests/diff_tests.rs`)共用这里的用例。
//! 同一 `seed` 永远生成相同的用例集。
//!
//! 内嵌 SplitMix64 RNG,避免为此引入 rand 依赖。

/// 确定性 RNG(SplitMix64)
pub struct DetRng {
    state: u64,
}

impl DetRng {
    pub fn new(seed: u64) -> Self {
        Self { state: seed }
    }

    pub fn next_u64(&mut self) -> u64 {
        self.state = self.state.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.state;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    /// [start, end)
    pub fn gen_range(&mut self, range: std::ops::Range<usize>) -> usize {
        let span = range.end - range.start;
        range.start + (self.next_u64() as usize % span)
    }

    /// 概率 p 的伯努利事件
    pub fn gen_bool(&mut self, p: f64) -> bool {
        (self.next_u64() as f64 / u64::MAX as f64) < p
    }
}

pub const BASES: [u8; 4] = [b'A', b'C', b'G', b'T'];

// LocalContextFlags 与 cpp_code/PoaDraft.cpp 保持一致
pub const ADAPTER_BEFORE: i32 = 1;
pub const ADAPTER_AFTER: i32 = 2;

/// 测试用例生成的反向互补(ACGT;与 src/dna.rs 表的一致子集)
pub fn revcomp(seq: &[u8]) -> Vec<u8> {
    seq.iter()
        .rev()
        .map(|&b| match b {
            b'A' => b'T',
            b'T' => b'A',
            b'C' => b'G',
            b'G' => b'C',
            other => other,
        })
        .collect()
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct TestRead {
    pub seq: String,
    /// Subread.flags 位组合
    pub flags: i32,
    /// poa_consensus_v2 使用;None 的 read 会被过滤
    pub is_fwd: Option<bool>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct TestSetting {
    pub min_identity: f32,
    pub match_score: i32,
    pub mismatch_score: i32,
    pub insertion_score: i32,
    pub deletion_score: i32,
    pub ed_unify_strand: i32,
    pub version: i32,
}

impl Default for TestSetting {
    fn default() -> Self {
        Self {
            min_identity: 0.82,
            match_score: 3,
            mismatch_score: -5,
            insertion_score: -2,
            deletion_score: -2,
            ed_unify_strand: 1,
            version: 1,
        }
    }
}

/// mode: "gen" -> poa_consensus, "fwd" -> poa_consensus_fwd, "v2" -> poa_consensus_v2
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct TestCase {
    pub name: String,
    pub mode: String,
    pub reads: Vec<TestRead>,
    pub setting: TestSetting,
}

impl crate::xpoa::TSubread for TestRead {
    fn get_seq(&self) -> &str {
        &self.seq
    }
    fn get_cx(&self) -> u8 {
        // flags 值域为 LocalContextFlags 位组合(<256)
        self.flags as u8
    }
    fn is_fwd(&self) -> Option<bool> {
        self.is_fwd
    }
}

fn random_seq(rng: &mut DetRng, len: usize) -> String {
    (0..len)
        .map(|_| BASES[rng.gen_range(0..4)] as char)
        .collect()
}

/// 按错误率注入替换/插入/缺失(类型均匀随机),近似测序错误模型
fn mutate(rng: &mut DetRng, seq: &str, err_rate: f64) -> String {
    let mut out = Vec::with_capacity(seq.len());
    for base in seq.bytes() {
        if rng.gen_bool(err_rate) {
            match rng.gen_range(0..3) {
                0 => out.push(BASES[rng.gen_range(0..4)]), // 替换
                1 => {
                    out.push(BASES[rng.gen_range(0..4)]); // 插入
                    out.push(base);
                }
                _ => {} // 缺失
            }
        } else {
            out.push(base);
        }
    }
    String::from_utf8(out).unwrap()
}

fn reads_from_reference(
    rng: &mut DetRng,
    reference: &str,
    n_reads: usize,
    err_rate: f64,
) -> Vec<String> {
    (0..n_reads)
        .map(|_| mutate(rng, reference, err_rate))
        .collect()
}

fn with_flags(reads: Vec<String>, flags: i32) -> Vec<TestRead> {
    reads
        .into_iter()
        .map(|seq| TestRead {
            seq,
            flags,
            is_fwd: Some(true),
        })
        .collect()
}

/// 主体维度组合 + 边缘 case。所有随机性都由 case 索引派生,保证可复现。
pub fn generate_cases() -> Vec<TestCase> {
    let mut cases = Vec::new();
    let default_setting = TestSetting::default();
    let mut push = |name: String, mode: &str, reads: Vec<TestRead>, setting: TestSetting| {
        cases.push(TestCase {
            name,
            mode: mode.to_string(),
            reads,
            setting,
        });
    };

    // ---- 主体组合: ref_len x err x n_reads x version x unify ----
    for (li, &ref_len) in [50usize, 500, 5000].iter().enumerate() {
        for (ei, &err_rate) in [0.05f64, 0.10, 0.15].iter().enumerate() {
            for (ni, &n_reads) in [1usize, 3, 10, 50].iter().enumerate() {
                for &version in [1i32, 2].iter() {
                    for &unify in [0i32, 1].iter() {
                        let mut rng = DetRng::new(
                            1000 * li as u64
                                + 100 * ei as u64
                                + 10 * ni as u64
                                + version as u64
                                + unify as u64,
                        );
                        let reference = random_seq(&mut rng, ref_len);
                        let reads = reads_from_reference(&mut rng, &reference, n_reads, err_rate);
                        let mut setting = default_setting.clone();
                        setting.version = version;
                        setting.ed_unify_strand = unify;
                        push(
                            format!("grid_l{ref_len}_e{err_rate}_n{n_reads}_v{version}_u{unify}"),
                            "gen",
                            with_flags(reads, ADAPTER_BEFORE | ADAPTER_AFTER),
                            setting,
                        );
                    }
                }
            }
        }
    }

    // ---- flags 组合(影响 n_passes) ----
    for &version in [1i32, 2].iter() {
        for (fi, &flags) in [
            ADAPTER_BEFORE | ADAPTER_AFTER, // 全部满足 n_passes 条件
            0,                              // 无任何 context
            -1,                             // 混合,见下方
        ]
        .iter()
        .enumerate()
        {
            let mut rng = DetRng::new(9000 + fi as u64 * 10 + version as u64);
            let reference = random_seq(&mut rng, 500);
            let n_reads = 20;
            let reads_raw = reads_from_reference(&mut rng, &reference, n_reads, 0.10);
            let reads = match flags {
                -1 => {
                    // 混合:一部分有双 adapter、一部分只有一边、一部分全无
                    reads_raw
                        .into_iter()
                        .enumerate()
                        .map(|(i, seq)| TestRead {
                            seq,
                            flags: match i % 4 {
                                0 => ADAPTER_BEFORE | ADAPTER_AFTER,
                                1 => ADAPTER_BEFORE,
                                2 => 0,
                                _ => ADAPTER_AFTER,
                            },
                            is_fwd: Some(true),
                        })
                        .collect()
                }
                f => with_flags(reads_raw, f),
            };
            let mut setting = default_setting.clone();
            setting.version = version;
            push(format!("flags_{fi}_v{version}"), "gen", reads, setting);
        }
    }

    // ---- 混合方向(ed_unify_strand=1 时 C++ 端自行定向) ----
    for &ref_len in [500usize, 5000].iter() {
        let mut rng = DetRng::new(2000 + ref_len as u64);
        let reference = random_seq(&mut rng, ref_len);
        let reads_raw = reads_from_reference(&mut rng, &reference, 20, 0.10);
        let reads = reads_raw
            .into_iter()
            .enumerate()
            .map(|(i, seq)| TestRead {
                seq: seq.clone(),
                flags: ADAPTER_BEFORE | ADAPTER_AFTER,
                is_fwd: Some(i % 3 != 0), // 1/3 反向
            })
            .collect();
        push(
            format!("mixed_dir_l{ref_len}"),
            "v2",
            reads,
            default_setting.clone(),
        );
    }

    // ---- 极端错误率(20%)+ min_identity 变体 ----
    for &min_identity in [0.82f32, 0.5, 0.99].iter() {
        let mut rng = DetRng::new(3000 + (min_identity * 1000.0) as u64);
        let reference = random_seq(&mut rng, 500);
        let reads = reads_from_reference(&mut rng, &reference, 20, 0.20);
        let mut setting = default_setting.clone();
        setting.min_identity = min_identity;
        push(
            format!("hi_err_id_{min_identity}"),
            "gen",
            with_flags(reads, ADAPTER_BEFORE | ADAPTER_AFTER),
            setting,
        );
    }

    // ---- 边缘 case ----
    {
        // 单条 read
        let mut rng = DetRng::new(4001);
        let reference = random_seq(&mut rng, 200);
        push(
            "edge_single_read".into(),
            "gen",
            with_flags(vec![reference], ADAPTER_BEFORE | ADAPTER_AFTER),
            default_setting.clone(),
        );

        // 全部相同 read
        push(
            "edge_identical_reads".into(),
            "gen",
            with_flags(
                vec!["AACGGATCGGA".into(); 4],
                ADAPTER_BEFORE | ADAPTER_AFTER,
            ),
            default_setting.clone(),
        );

        // 1-3bp 超短 read
        push(
            "edge_very_short_mixed".into(),
            "gen",
            with_flags(
                vec![
                    "A".into(),
                    "C".into(),
                    "AC".into(),
                    "GT".into(),
                    "ACG".into(),
                ],
                ADAPTER_BEFORE | ADAPTER_AFTER,
            ),
            default_setting.clone(),
        );

        // 全同聚物
        push(
            "edge_homopolymer".into(),
            "gen",
            with_flags(vec!["A".repeat(120); 8], ADAPTER_BEFORE | ADAPTER_AFTER),
            default_setting.clone(),
        );

        // 含 N 的 read(BaseCode 将 N 视为 A)
        {
            let mut rng = DetRng::new(4002);
            let reference = random_seq(&mut rng, 300);
            let mut reads_raw = reads_from_reference(&mut rng, &reference, 10, 0.05);
            reads_raw[0] = format!("{}N{}", "A".repeat(10), &reference[10..100]);
            push(
                "edge_with_n".into(),
                "gen",
                with_flags(reads_raw, ADAPTER_BEFORE | ADAPTER_AFTER),
                default_setting.clone(),
            );
        }

        // 构造锚点位于共识末尾附近的 case(version=2 的 RangeFinderV2 边界)
        // reads 与 reference 首尾均有完全匹配段,错误集中在中间
        {
            let mut rng = DetRng::new(4003);
            let head = random_seq(&mut rng, 50);
            let tail = random_seq(&mut rng, 50);
            let mid_len = 400;
            let mid: String = random_seq(&mut rng, mid_len);
            let reads: Vec<String> = (0..10)
                .map(|_| {
                    let mut mutated = mutate(&mut rng, &mid, 0.12);
                    if rng.gen_bool(0.3) {
                        // 尾部随机截断,制造锚点位置差异
                        let cut = rng.gen_range(1..6);
                        mutated.truncate(mutated.len() - cut);
                    }
                    format!("{head}{mutated}{tail}")
                })
                .collect();
            let mut setting = default_setting.clone();
            setting.version = 2;
            push(
                "edge_tail_anchor_v2".into(),
                "gen",
                with_flags(reads, ADAPTER_BEFORE | ADAPTER_AFTER),
                setting,
            );
        }

        // 注:空字符串 read 不纳入差分 —— C++ 后端(PoaDraftGen)对空 read
        // 会 segfault(threadFirstRead 对空序列 add_edge(null_vertex, $)),
        // 属于不可复制的 UB。Rust 后端对空 read 显式 panic,语义等价于
        // "非法输入不受支持",且给出可读的错误信息。
    }

    cases
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cases_are_deterministic() {
        let a = generate_cases();
        let b = generate_cases();
        assert_eq!(a, b);
        assert!(!a.is_empty());
    }

    #[test]
    fn mutate_changes_something_at_high_err() {
        let mut rng = DetRng::new(42);
        let seq = "ACGTACGTACGT".to_string();
        assert_ne!(mutate(&mut rng, &seq, 0.9), seq);
    }
}
